def product_array(numbers):
    n = len(numbers)
    if n < 2:
        raise ValueError("Array must contain at least two elements.")
    left_products = [1] * n
    right_products = [1] * n
    result = [1] * n

    for i in range(1, n):
        left_products[i] = left_products[i - 1] * numbers[i - 1]

    for i in range(n - 2, -1, -1):
        right_products[i] = right_products[i + 1] * numbers[i + 1]

