    bridge = []
    queue = []

    for i, c in enumerate(ants):
        if terrain[i] == '.':
            queue.append((i, c))
        else:
            bridge.append((i, c))

    while queue:
        x, c = queue.pop()
        if x < len(terrain) - 1 and terrain[x + 1] == '.':
            queue.append((x + 1, c))
        elif x > 0 and terrain[x - 1] == '.':
            queue.append((x - 1, c))
        else:
            bridge.append((x, c))

    result = []
